CREATE TABLE `member_users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `full_name` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role_id` bigint unsigned DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `phone_mobile` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone_landline` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profile_completed` tinyint(1) NOT NULL DEFAULT '0',
  `approved_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `birth_date` date DEFAULT NULL,
  `birth_place` varchar(140) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `profile_photo_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `institutional_role` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `member_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `privacy_notice_version` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `privacy_notice_accepted_at` datetime DEFAULT NULL,
  `cpf` varchar(14) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `postal_code` varchar(9) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `street_address` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address_complement` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `neighborhood` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address_city` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address_state` char(2) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `preferred_due_day` tinyint unsigned DEFAULT NULL,
  `contribution_amount` decimal(10,2) DEFAULT NULL,
  `contribution_plan_label` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `preferred_payment_method` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `billing_email_opt_in` tinyint(1) NOT NULL DEFAULT '0',
  `billing_whatsapp_opt_in` tinyint(1) NOT NULL DEFAULT '0',
  `association_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'applicant',
  `is_contributor` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `uq_member_users_cpf` (`cpf`)
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
