--
-- Table structure for table `member_contribution_charges`
--

DROP TABLE IF EXISTS `member_contribution_charges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `member_contribution_charges` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `member_user_id` bigint unsigned NOT NULL,
  `competence` char(7) COLLATE utf8mb4_unicode_ci NOT NULL,
  `due_date` date NOT NULL,
  `amount_due` decimal(10,2) NOT NULL DEFAULT '0.00',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `preferred_payment_method` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_recorded_method` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL,
  `exemption_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `generated_by_user_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `gateway_provider` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_customer_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_payment_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_billing_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_status` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_invoice_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_bank_slip_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_transaction_receipt_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gateway_pix_payload` longtext COLLATE utf8mb4_unicode_ci,
  `gateway_pix_encoded_image` longtext COLLATE utf8mb4_unicode_ci,
  `gateway_pix_expiration_date` datetime DEFAULT NULL,
  `gateway_last_synced_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_member_contribution_charge_member_competence` (`member_user_id`,`competence`),
  KEY `idx_member_contribution_charge_status_due` (`status`,`due_date`),
  KEY `idx_member_contribution_charge_member` (`member_user_id`),
  CONSTRAINT `fk_member_contribution_charge_member` FOREIGN KEY (`member_user_id`) REFERENCES `member_users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

