  `acted_by_user_id` bigint unsigned DEFAULT NULL,
  `payload_json` longtext COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_member_contribution_events_charge` (`charge_id`),
  KEY `idx_member_contribution_events_member` (`member_user_id`),
  CONSTRAINT `fk_member_contribution_events_charge` FOREIGN KEY (`charge_id`) REFERENCES `member_contribution_charges` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_member_contribution_events_member` FOREIGN KEY (`member_user_id`) REFERENCES `member_users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
